CREATE TABLE IF NOT EXISTS public.field_soil_profiles (
    field_id TEXT,
    area_ha DOUBLE PRECISION,
    centroid_lat DOUBLE PRECISION,
    centroid_lon DOUBLE PRECISION,
    crop_code INTEGER,
    crop TEXT,
    h3_cells_count INTEGER,
    sand_pct DOUBLE PRECISION,
    silt_pct DOUBLE PRECISION,
    clay_pct DOUBLE PRECISION,
    sand_min_pct DOUBLE PRECISION,
    sand_max_pct DOUBLE PRECISION,
    ph DOUBLE PRECISION,
    ph_min DOUBLE PRECISION,
    ph_max DOUBLE PRECISION,
    om DOUBLE PRECISION,
    cec DOUBLE PRECISION,
    bulk_density DOUBLE PRECISION,
    soilTexture TEXT,
    band_ph TEXT,
    band_om TEXT,
    band_cec TEXT,
    wilting_point DOUBLE PRECISION,
    field_capacity DOUBLE PRECISION,
    awc_mm_per_m DOUBLE PRECISION,
    permeability TEXT,
    water_retention TEXT,
    soil_method_note TEXT,
    soil_variability TEXT
);

